head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldfil40400";

// [A] 초기 목록 미해결 — 진입 URL 이 «고치는» 제출로 보인다(/outer/reisuPw.do?method=registerPasswordReissuanceForm) — 열자마자 부를 수 없다

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldfil40400.onpageload' });
    }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name btn_PopZipCode_onclick
 * @description 「우편번호」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_PopZipCode_onclick = async function(e){
    try {
        await scwin.popZipCode()

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40400.btn_PopZipCode_onclick' }); }
};

/**
 * @method
 * @name slc_selApctEmail_onchange
 * @description 「메일주소」 변경 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.slc_selApctEmail_onchange = function(e){
    try {
        ((s, t) => { if (t && t.setValue) { t.setValue((s && s.getValue) ? s.getValue() : ""); } const i = (s && typeof s.getSelectedIndex === "function") ? s.getSelectedIndex() : -1; if (i === 0 && t && t.focus) { t.focus(); } })($c.util.getComponent("slc_selApctEmail"), $c.util.getComponent('ipt_apctEmail2'));

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldfil40400.slc_selApctEmail_onchange' }); }
};

/**
 * @method
 * @name btn_Confirm_onclick
 * @description 「확인」 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Confirm_onclick = async function(e){
    try {
        await scwin.confirm()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldfil40400.btn_Confirm_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm
 * @description Confirm 서버 호출
 * @param {String} action 제출 주소(호출부가 as-is form.action 으로 정하던 분기별 URL · 생략 시 기본 주소)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm = async function (action) {
    const sbmOptions = {
        id: "tx_fn_Confirm",
        method: "post",
        action: action ?? "/register/reisuPw.do",
        ref: "dma_ConfirmReq",
        target: "dlt_codeVOList=body.content",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name tx_fn_Confirm_xhr
 * @description Confirm xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Confirm_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Confirm_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Confirm_xhr", unresolved: "action:self_submit:tx_fn_Confirm_xhr" };
};

/**
 * @method
 * @name popZipCode
 * @description pop Zip Code 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.popZipCode = async function () {
    const zipSearchURL = '/jldinf90009/jldinf90009.xml';
    scwin.setZipCode_recv(await $c.win.openPopup(zipSearchURL, { id: "zipWin", scrollbars: false, resizable: false, width: "445", height: "600", type: "pageFramePopup" }, { method: "loadInitPage" }));
};

/**
 * @method
 * @name setZipCode
 * @description set Zip Code 처리
 * @param {*} _zipCode _zipCode
 * @param {*} _address _address
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode = function (_zipCode, _address) {
    $c.util.getComponent("ipt_locZipcd").setValue(_zipCode);
    $c.util.getComponent("ipt_locAddr").setValue(_address);
};

/**
 * @method
 * @name confirm
 * @description confirm 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.confirm = async function () {
    const frm = (document.reisuPwForm || { elements: [] });
    if (await $c.fil.checkRequired($c.util.getComponent("slc_corpUsrTpCd"), "사용자1")) {  // as-is alt="사용자1" + checkRequired(DOM)
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_apctId'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_isurCd'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "상장회사명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_corpNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_corpRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_corpRegNo').getValue().length !== 13) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_corpRegNo')) + '는 13자리입니다.');
        $c.util.getComponent("ipt_corpRegNo").focus();
        return;
    }
    if (!$c.fil.isNumberInput($c.util.getComponent('ipt_corpRegNo'))) {
        await $c.win.alert('법인등록번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_bzRegNo'))) {
        return;
    }
    if ($c.util.getComponent('ipt_bzRegNo').getValue().length !== 10) {
        await $c.win.alert(((__a) => ((__a && __a.getAttribute) ? ((__a.getAttribute("alt") || __a.getAttribute("toolTip") || (__a.getTitle ? (__a.getTitle() ?? "") : "")) || "") : (__a ? (__a.alt ?? "") : "")))($c.util.getComponent('ipt_bzRegNo')) + '는 10자리입니다.');
        $c.util.getComponent("ipt_bzRegNo").focus();
        return;
    }
    if (!$c.fil.isNumberInput($c.util.getComponent('ipt_bzRegNo'))) {
        await $c.win.alert('사업자등록번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_repNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "대표자명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_repNm'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_locZipcd')))) {
        await $c.win.alert('우편번호는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_apctNm'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "신청인 성명"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_apctNm'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_apctTelNo1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_apctTelNo2')) || await $c.fil.checkRequired($c.util.getComponent('ipt_apctTelNo3'))) {
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_apctTelNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_apctTelNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_apctTelNo3')))) {
        await $c.win.alert('신청인 전화번호는 숫자만 입력하세요');
        return;
    }
    if (!($c.fil.isNumberInput($c.util.getComponent('ipt_apctFaxNo1')) && $c.fil.isNumberInput($c.util.getComponent('ipt_apctFaxNo2')) && $c.fil.isNumberInput($c.util.getComponent('ipt_apctFaxNo3')))) {
        await $c.win.alert('FAX는 숫자만 입력하세요');
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_apctEmail1')) || await $c.fil.checkRequired($c.util.getComponent('ipt_apctEmail2'))) {
        return;
    }
    if (await $c.fil.checkRequired($c.util.getComponent('ipt_reisuRsn'))) {
        return;
    }
    if (await (async (c) => { const v = String((c && c.getValue) ? (c.getValue() ?? "") : ""); const max = Number((c && c.getUserData) ? ((c.getUserData("maxByteLength") || c.getUserData("maxLength")) ?? 0) : 0) || 0; if (max && $c.str.getByteLength(v) > max) { const lbl = "재발급사유"; await $c.win.alert((lbl ? ("'" + lbl + "' 항목은 ") : "") + "한글 " + (max / 2) + "자, 영문 " + max + "자까지 가능합니다."); return true; } return false; })($c.util.getComponent('ipt_reisuRsn'))) {
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('apctTelNo', $c.util.getComponent('ipt_apctTelNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctTelNo3').getValue());
    if (!$c.util.isEmpty(($c.util.getComponent('ipt_apctFaxNo1')).getValue()) && !$c.util.isEmpty(($c.util.getComponent('ipt_apctFaxNo2')).getValue()) && !$c.util.isEmpty(($c.util.getComponent('ipt_apctFaxNo3')).getValue())) {
        $c.util.getComponent('dma_ConfirmReq').set('apctFaxNo', $c.util.getComponent('ipt_apctFaxNo1').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo2').getValue()+ '-' + $c.util.getComponent('ipt_apctFaxNo3').getValue());
    }
    if (!($c.fil.isZipCodeInput($c.util.getComponent('ipt_locZipcd')))) {
        await $c.win.alert('우편번호는 숫자만 입력하세요');
        return false;
    }
    $c.util.getComponent('dma_ConfirmReq').set('apctEmail', $c.str.trim($c.util.getComponent('ipt_apctEmail1').getValue()) + '@' + $c.str.trim($c.util.getComponent('ipt_apctEmail2').getValue()));
    if (!$c.str.isEmail($c.util.getComponent('dma_ConfirmReq').get('apctEmail'))) {
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('method', "passwordReissuanceIdCheck");
    frm.action = "reisuPw.do";
    let result = await scwin.tx_fn_Confirm_xhr();
    result = $c.str.trim(result);
    if (result !== "success") {
        await $c.win.alert('입력하신 정보에 대한 아이디가 없습니다.\n사용자 구분, 아이디, 회사코드를 확인하세요.');
        return;
    }
    $c.util.getComponent('dma_ConfirmReq').set('method', "registerPasswordReissuance");
    await scwin.tx_fn_Confirm('reisuPw.do');
};

/**
 * @method
 * @name chgCorpUsrTpCd
 * @description chg Corp Usr Tp Cd 처리
 * @returns {void}
 * @hidden N
 */
scwin.chgCorpUsrTpCd = function () {
    const corpUsrTpCd = $c.util.getComponent('slc_corpUsrTpCd').getValue();
    let isurCdTitle;
    if (corpUsrTpCd === '14') {
        isurCdTitle = '대상회사코드(5자리)';
    } else {
        isurCdTitle = '회사코드(5자리)';
    }
    ($c.util.getComponent('isurCdTitle') && $c.util.getComponent('isurCdTitle').setValue) ? $c.util.getComponent('isurCdTitle').setValue("<img src='/img/main/check.gif' align='absmiddle'/> " + isurCdTitle) : (($c.util.getComponent('isurCdTitle') && $c.util.getComponent('isurCdTitle').setText) ? $c.util.getComponent('isurCdTitle').setText("<img src='/img/main/check.gif' align='absmiddle'/> " + isurCdTitle) : (console.warn('[sdd] 값 쓰기 미지원 컴포넌트: ' + 'isurCdTitle'), void ("<img src='/img/main/check.gif' align='absmiddle'/> " + isurCdTitle)));
};

/**
 * @method
 * @name setZipCode_recv
 * @description 팝업 회신 수신 — 팝업이 남긴 인자를 as-is 함수 인자 순서로 펼쳐 넘긴다.
 * @param {*} r r
 * @returns {void}
 * @hidden N
 */
scwin.setZipCode_recv = function (r) { if (!r) return; let a = Array.isArray(r) ? r : [r]; if (a[0] && a[0].__sdd_rec) { const rec = a[0]; const nm = function (s) { return s.replace(/_/g, '').toLowerCase(); }; const ps = (String(scwin.setZipCode).match(/\(([^)]*)\)/) || ['', ''])[1].split(',').map(function (s) { return s.trim(); }).filter(Boolean); const nk = {}; for (let k in rec) nk[nm(k)] = rec[k]; a = ps.map(function (p) { return nk[nm(p)]; }); } try { scwin.setZipCode.apply(null, a); } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'popup-recv' }); } };
